use chrono::NaiveDate; use proptest::prelude::*; use taskdeck_core::ics::{Limits, parse}; use taskdeck_core::time::FixedZone;
fn window() -> (NaiveDate, NaiveDate) { (NaiveDate::from_ymd_opt(2026, 9, 24).unwrap_or(NaiveDate::MIN), NaiveDate::from_ymd_opt(2027, 12, 29).unwrap_or(NaiveDate::MAX)) }
fn repeated_byday() -> String { let days = vec!["MO"; 40_000].join(","); format!("BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nDTSTART;VALUE=DATE:00010101\r\nRRULE:FREQ=MONTHLY;BYDAY={days}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n") }
proptest! { #![proptest_config(ProptestConfig { timeout: 30_000, cases: 1, ..ProptestConfig::default() })]
  #[test] fn a_repeated_byday_returns_in_bounded_time(_x in Just(())) { let (from, until) = window(); let text = repeated_byday(); prop_assert!(text.len() < 200_000); let _ = parse(&text, from, until, Limits::default(), &FixedZone(0)); } }

Measured in release with a clock (a scratch test, not for the crate): 120,107 bytes take 109.2 s and give Ok(66 occurrences). The time grows linearly with the BYDAY count (n=10: 33 ms, n=100: 377 ms, n=400: 1.25 s), so the 8 MiB fetch cap (about 2.8M entries) would mean hours. Cause: expand (ics.rs:968-1056) does up to 24,000 monthly steps. On each step, month_days (ics.rs:1114-1117) calls nth_weekday once per BYDAY entry, and each call builds a 31-day Vec. The entries are pushed without dedup at ics.rs:879. WEEKLY (week_days) and BYSETPOS (apply_set_pos) also do work per entry on each step.

